// Retexia — Post (plan + design). EDIT only the values marked EDIT. API keys live in n8n credentials.
const CONFIG = {
  retexiaKey: 'EDIT: the same value as N8N_POST_KEY in the Retexia panels (Vercel)',
  supabaseUrl: 'https://axommwxevnfpljroejmc.supabase.co', // the Retexia Supabase project
  openaiBase: 'https://api.openai.com/v1',
  textModel: 'gpt-6-luna',
  imageModel: 'gpt-image-2.5-flare', // new design from text
  imageEditModel: 'gpt-image-2.5-sunburst', // design that includes the brand logo
  imageQuality: 'medium', // 'high' = sharper text on the design (better for Sinhala/Tamil letters), costs more
  feedSize: '1088x1360', // 4:5 feed post
  storySize: '1088x1920', // 9:16 story
  useLogo: true, // put brand.logo_path on the design when the business has one
  costs: { text: 0.002, image: 0.04, imageEdit: 0.05 }, // USD, only for usage_monthly
};

// Only Retexia may call this webhook (header X-Retexia-Key).
const input = $input.first().json;
const headers = input.headers || {};
if (!CONFIG.retexiaKey || CONFIG.retexiaKey.startsWith('EDIT') || String(headers['x-retexia-key'] || '') !== CONFIG.retexiaKey) {
  throw new Error('Unauthorized: missing or wrong X-Retexia-Key (set retexiaKey in Config).');
}
const body = input.body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const uuidOr = (v) => (UUID.test(String(v || '').toLowerCase()) ? String(v).toLowerCase() : '');
const businessId = uuidOr(body.business_id);
if (!businessId) throw new Error('business_id is missing or not a UUID.');
const action = body.action === 'plan' ? 'plan' : 'design';
const CAPTION = ['si', 'si_en', 'singlish', 'en', 'ta'];
const DESIGN = ['si', 'en', 'ta'];
const captionLanguage = CAPTION.includes(body.caption_language) ? body.caption_language : 'en';
const designLanguage = DESIGN.includes(body.design_language) ? body.design_language : 'en';

if (action === 'plan') {
  const slots = (Array.isArray(body.slots) ? body.slots : []).slice(0, 10).map((s) => ({
    key: String(s.key || ''), format: s.format === 'story' ? 'story' : 'post', time: String(s.time || ''), hint: s.hint ? String(s.hint).slice(0, 400) : '',
  })).filter((s) => s.key);
  if (!slots.length) throw new Error('No slots to plan.');
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(body.date || '')) ? body.date : new Date().toISOString().slice(0, 10);
  const promptLanguage = ['si', 'en', 'ta'].includes(body.prompt_language) ? body.prompt_language : 'en';
  return [{ json: { ...CONFIG, action, businessId, date, slots, captionLanguage, designLanguage, promptLanguage } }];
}

const prompt = String(body.prompt || '').trim();
if (prompt.length < 3) throw new Error('Send a prompt describing the post.');
return [{ json: {
  ...CONFIG, action, businessId,
  postId: uuidOr(body.post_id),
  prompt: prompt.slice(0, 1600),
  format: body.format === 'story' ? 'story' : 'post',
  captionLanguage, designLanguage,
  publish: body.publish === true,
  scheduledAt: typeof body.scheduled_at === 'string' ? body.scheduled_at : '',
} }];

// One text call writes the whole day's playlist: one idea (prompt) per slot.
const cfg = $('Config').first().json;
const ctx = $input.first().json.ctx;
if (!ctx || !ctx.business) throw new Error('Business not found: ' + cfg.businessId);
const b = ctx.business;
const brand = b.brand || {};
const LANG = { si: 'Sinhala (Sinhala script)', en: 'English', ta: 'Tamil (Tamil script)' };
const money = (p) => (p.price == null ? 'no price' : `${p.currency || ''} ${Number(p.price).toLocaleString('en-US')}`.trim());
const facts = [
  `Business: ${b.name}${b.category ? ` (${b.category})` : ''}${b.country ? `, ${b.country}` : ''}`,
  b.brand_brief && `About: ${b.brand_brief}`,
  (ctx.products || []).length && `Products: ${ctx.products.map((p) => `${p.name} = ${money(p)}${p.description ? ` (${p.description})` : ''}`).join('; ')}`,
  (ctx.offers || []).length && `Active offers: ${ctx.offers.map((o) => `${o.title}${o.discount ? `, ${o.discount}` : ''}${o.price ? `, ${o.price}` : ''}, ends ${o.ends}${o.details ? ` (${o.details})` : ''}`).join('; ')}`,
  brand.contact && `Contact: ${JSON.stringify(brand.contact)}`,
].filter(Boolean);

const instructions = [
  'You plan one day of Facebook and Instagram content for a small business in Sri Lanka.',
  'For every SLOT write one idea that a designer AI will turn into a finished picture (and, for posts, a caption).',
  'Use ONLY the FACTS and the slot HINT. Never invent prices, discounts, dates, phone numbers or claims.',
  'If a slot has a HINT (an offer or the owner\'s note), that slot must be about it.',
  'Vary the angles across the day: product showcase, useful tip, behind the scenes, customer favourite, offer, question to the audience, seasonal or local moment. Spread the products; do not repeat an idea from RECENT.',
  'post slots: a feed post (4:5 picture + caption). story slots: a quick full-screen story with one short message (today-only reminder, close-up, question, countdown).',
  `title: max 6 words. prompt: 1-3 concrete sentences: what to show, which product (and its price only if in FACTS), the message and the feeling. Write title and prompt in ${LANG[cfg.promptLanguage] || 'English'}.`,
  'angle: one or two words in English (e.g. showcase, tip, offer). product: the product name from FACTS, or "".',
  'Return exactly one item per SLOT, with the same key.',
].join('\n');

const slots = cfg.slots.map((s) => `- key=${s.key} | ${s.format} at ${s.time}${s.hint ? ` | HINT: ${s.hint}` : ''}`);
const recent = (ctx.recent_prompts || []).map((p) => '- ' + String(p).replace(/\s+/g, ' '));
const userText = [`DATE: ${cfg.date}`, '', 'FACTS:', ...facts.map((f) => '- ' + f), '', 'SLOTS:', ...slots, recent.length ? '\nRECENT (do not repeat):\n' + recent.join('\n') : ''].join('\n');

const str = { type: 'string' };
const schema = {
  type: 'object', additionalProperties: false, required: ['items'],
  properties: { items: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['key', 'title', 'prompt', 'angle', 'product'],
    properties: { key: str, title: str, prompt: str, angle: str, product: str } } } },
};
return [{ json: { body: {
  model: cfg.textModel, instructions,
  input: [{ role: 'user', content: [{ type: 'input_text', text: userText }] }],
  text: { format: { type: 'json_schema', name: 'day_playlist', strict: true, schema } },
  max_output_tokens: 6000,
} } }];

const res = $input.first().json;
let text = res.output_text;
if (!text) for (const o of res.output || []) for (const c of o.content || []) { if (c.type === 'output_text') text = c.text; if (c.type === 'refusal') throw new Error('OpenAI refused: ' + c.refusal); }
let out;
try { out = JSON.parse(text); } catch (e) { throw new Error('Bad JSON from OpenAI: ' + String(text).slice(0, 300)); }
const keys = new Set($('Config').first().json.slots.map((s) => s.key));
const items = (out.items || []).filter((i) => keys.has(i.key) && String(i.prompt || '').trim().length > 3)
  .map((i) => ({ key: i.key, title: String(i.title || '').slice(0, 120), prompt: String(i.prompt).trim().slice(0, 1500), angle: String(i.angle || '').slice(0, 60), product: String(i.product || '').slice(0, 120) }));
return [{ json: { items } }];

// One text call writes the captions AND the design brief (with the exact text for the picture).
const cfg = $('Config').first().json;
const ctx = $input.first().json.ctx;
if (!ctx || !ctx.business) throw new Error('Business not found: ' + cfg.businessId);
const b = ctx.business;
const brand = b.brand || {};
const story = cfg.format === 'story';
const money = (p) => (p.price == null ? 'no price' : `${p.currency || ''} ${Number(p.price).toLocaleString('en-US')}`.trim());
const facts = [
  `Business: ${b.name}${b.category ? ` (${b.category})` : ''}${b.country ? `, ${b.country}` : ''}`,
  b.brand_brief && `About: ${b.brand_brief}`,
  brand.tone && `Tone: ${typeof brand.tone === 'string' ? brand.tone : JSON.stringify(brand.tone)}`,
  brand.emoji === false ? 'Emoji: none' : 'Emoji: a few are fine',
  (brand.always_words || []).length && `Words the brand likes: ${brand.always_words.join(', ')}`,
  (brand.never_words || []).length && `NEVER use: ${brand.never_words.join(', ')}`,
  brand.contact && `Contact: ${JSON.stringify(brand.contact)}`,
  (ctx.products || []).length && `Products: ${ctx.products.map((p) => `${p.name} = ${money(p)}${p.description ? ` (${p.description})` : ''}`).join('; ')}`,
].filter(Boolean);

const CAPTION = {
  si: 'Sinhala, in Sinhala script (Unicode). Natural, everyday Sri Lankan Sinhala as people really speak: warm, simple, short sentences; not formal or literary. Keep product names, prices and phone numbers exactly as in FACTS.',
  si_en: 'Sinhala in Sinhala script (natural everyday Sri Lankan Sinhala), then one short English line with the same call to action.',
  singlish: 'Singlish: Sinhala words written in English letters, the way Sri Lankans text each other (e.g. "Ada vitharai!", "Order karanna message ekak danna"). No Sinhala script.',
  en: 'Simple, friendly English for Sri Lankan customers.',
  ta: 'Tamil, in Tamil script: natural Sri Lankan Tamil, warm and simple.',
};
const DESIGN = {
  si: 'Sinhala, in Sinhala script (Unicode Sinhala letters). Very short, common, correctly spelled words. Keep prices, phone numbers and brand names as written.',
  en: 'English. Very short, clear words.',
  ta: 'Tamil, in Tamil script. Very short, common, correctly spelled words. Keep prices, phone numbers and brand names as written.',
};

const instructions = [
  'You are a senior social media designer and copywriter for small businesses in Sri Lanka.',
  story
    ? 'Turn the REQUEST into one 9:16 STORY: a full-screen designed graphic with a few words. Stories show no caption, so caption_instagram and caption_facebook must be "" and hashtags [].'
    : 'Turn the REQUEST into one 4:5 feed post: a designed graphic (banner style, with text on it) plus captions.',
  'Use ONLY the FACTS and the REQUEST. Never invent prices, discounts, dates, phone numbers, addresses, links, awards, reviews, or health/income claims. If unsure, leave it out.',
  story ? '' : `caption_instagram in ${CAPTION[cfg.captionLanguage] || CAPTION.en} Hook in the first line, 2-4 short lines, one call to action, no hashtags.`,
  story ? '' : 'caption_facebook: same language and idea, slightly more conversational, no hashtags.',
  story ? '' : 'hashtags: 3-8, without #, mix local and topic tags (Latin letters are easier to find; Sinhala tags are fine too).',
  `Text on the design, in ${DESIGN[cfg.designLanguage] || DESIGN.en} headline max ${story ? 5 : 6} words (the big message); subline max ${story ? 8 : 12} words or ""; ` +
    'price_text only a price/discount stated in FACTS or REQUEST, else ""; cta max 4 words or ""; ' +
    'footer: one phone/website/handle copied exactly from Contact, else "".',
  'design_prompt: one paragraph of art direction for an image model (in English): a style that fits this business and its audience, ' +
    `the main visual (subject, setting, light), layout (where HEADLINE, SUBLINE, PRICE, CTA, FOOTER sit${story ? '; keep the top 14% and bottom 20% free of text' : ''}), colours, ` +
    'typography feel and mood. Refer to the texts only by those labels, do not write them out.',
  'alt_text: one plain English sentence describing the image.',
].filter(Boolean).join('\n');

const recent = (ctx.recent || []).map((c) => '- ' + String(c).replace(/\s+/g, ' '));
const userText = [`REQUEST: ${cfg.prompt}`, '', 'FACTS:', ...facts.map((f) => '- ' + f), recent.length ? '\nRecent posts (do not repeat their openings):\n' + recent.join('\n') : ''].filter((x) => x !== '').join('\n');

const str = { type: 'string' };
const schema = {
  type: 'object', additionalProperties: false,
  required: ['headline', 'subline', 'price_text', 'cta', 'footer', 'design_prompt', 'caption_instagram', 'caption_facebook', 'hashtags', 'alt_text'],
  properties: { headline: str, subline: str, price_text: str, cta: str, footer: str, design_prompt: str, caption_instagram: str, caption_facebook: str, hashtags: { type: 'array', items: str }, alt_text: str },
};
return [{ json: {
  factsText: facts.join('\n') + '\n' + cfg.prompt,
  body: { model: cfg.textModel, instructions, input: [{ role: 'user', content: [{ type: 'input_text', text: userText }] }],
          text: { format: { type: 'json_schema', name: 'post_design', strict: true, schema } }, max_output_tokens: 4000 },
} }];

// Read the copy, drop on-picture text with numbers not found in the facts, build the image prompt.
const cfg = $('Config').first().json;
const ctx = $('Load business').first().json.ctx;
const req = $('Build copy request').first().json;
const res = $('OpenAI: write post').first().json;
const logoSigned = $input.first().json.signedURL;
const b = ctx.business;
const brand = b.brand || {};
const story = cfg.format === 'story';

let text = res.output_text;
if (!text) for (const o of res.output || []) for (const c of o.content || []) { if (c.type === 'output_text') text = c.text; if (c.type === 'refusal') throw new Error('OpenAI refused: ' + c.refusal); }
let copy;
try { copy = JSON.parse(text); } catch (e) { throw new Error('Bad JSON from OpenAI: ' + String(text).slice(0, 300)); }

// Accuracy guard: every number on the design must appear in the facts or the request.
const blob = req.factsText.replace(/,/g, '');
const nums = (s) => (String(s).match(/\d[\d.,]*/g) || []).map((n) => n.replace(/[.,]+$/, '').replace(/,/g, ''));
const verified = (s) => nums(s).every((n) => blob.includes(n));
const dropped = [];
for (const k of ['headline', 'subline', 'price_text', 'cta', 'footer']) {
  copy[k] = String(copy[k] || '').trim();
  if (copy[k] && !verified(copy[k])) { dropped.push(`${k}: ${copy[k]}`); copy[k] = ''; }
}
if (!copy.headline) copy.headline = b.name;

const SCRIPT = {
  si: 'All words are SINHALA in Sinhala Unicode script. Render every Sinhala letter, vowel sign (pili) and conjunct exactly as given, in a clean modern Sinhala typeface (like Noto Sans Sinhala or Iskoola Pota). Never replace Sinhala with English letters or invent letters.',
  ta: 'All words are TAMIL in Tamil Unicode script. Render every Tamil letter and vowel sign exactly as given, in a clean modern Tamil typeface (like Noto Sans Tamil). Never replace Tamil with English letters.',
  en: '',
};
const lines = [
  ['HEADLINE (largest, boldest)', copy.headline],
  ['SUBLINE', copy.subline],
  ['PRICE (badge or tag)', copy.price_text],
  ['CTA (button style)', copy.cta],
  ['FOOTER (small)', copy.footer],
].filter(([, v]) => v).map(([k, v]) => `- ${k}: "${v}"`);

const useLogo = !!(cfg.useLogo && logoSigned);
const prompt = [
  `A finished, professional social media ${story ? 'STORY design (9:16 vertical, full screen)' : 'post design (4:5 feed)'} for "${b.name}"${b.category ? `, a ${b.category} business` : ''}${b.country ? ` in ${b.country}` : ''}.`,
  copy.design_prompt,
  (brand.colors || []).length ? `Brand colours: ${brand.colors.join(', ')}.` : '',
  brand.font ? `Typography in the style of: ${brand.font}.` : '',
  'TEXT ON THE DESIGN - render exactly as written, perfectly spelled, letter for letter, and no other words:',
  ...lines,
  SCRIPT[cfg.designLanguage] || '',
  story ? 'Keep the top 14% and the bottom 20% of the picture free of text (the app shows its own buttons there).' : '',
  useLogo ? 'Place the attached logo small in a top corner, exactly as it is.' : 'Do not draw any logo or brand mark.',
  'Clear hierarchy, high contrast, crisp typography, keep all text away from the outer edges. No watermarks, no extra text.',
].filter(Boolean).join('\n');

const body = {
  model: useLogo ? cfg.imageEditModel : cfg.imageModel,
  prompt,
  size: story ? cfg.storySize : cfg.feedSize,
  quality: cfg.imageQuality,
  output_format: 'jpeg',
  output_compression: 90,
  n: 1,
};
if (useLogo) body.images = [{ image_url: cfg.supabaseUrl + '/storage/v1' + logoSigned }];

const tags = story ? [] : (copy.hashtags || []).map((t) => '#' + String(t).replace(/^#+/, '').replace(/[^\p{L}\p{N}\p{M}_]/gu, '')).filter((t) => t.length > 1).slice(0, 8);
const ig = story ? '' : String(copy.caption_instagram || '').trim();
return [{ json: {
  endpoint: useLogo ? 'edits' : 'generations',
  body,
  caption: ig,
  variants: story ? {} : { facebook: { caption: String(copy.caption_facebook || '').trim() }, instagram: { caption: ig + (tags.length ? '\n\n' + tags.join(' ') : ''), hashtags: tags } },
  altText: String(copy.alt_text || '').trim(),
  brief: {
    headline: copy.headline, subline: copy.subline, price_text: copy.price_text, cta: copy.cta, footer: copy.footer,
    design_prompt: copy.design_prompt, alt_text: copy.alt_text, dropped_text: dropped, logo: useLogo,
    caption_language: cfg.captionLanguage, design_language: cfg.designLanguage, ...(cfg.postId ? {} : { prompt: cfg.prompt }),
  },
} }];

const res = $input.first().json;
const cfg = $('Config').first().json;
const b64 = res && res.data && res.data[0] && res.data[0].b64_json;
if (!b64) throw new Error('OpenAI returned no image: ' + JSON.stringify(res).slice(0, 300));
const fileName = `${cfg.format}-${Date.now()}.jpg`;
const bytes = Math.floor((b64.length * 3) / 4) - (b64.endsWith('==') ? 2 : b64.endsWith('=') ? 1 : 0);
return [{
  json: { storage_path: `${cfg.businessId}/ai/${fileName}`, bytes },
  binary: { data: { data: b64, mimeType: 'image/jpeg', fileName, fileExtension: 'jpg' } },
}];
